import pyAether as ae


def create_highlight_marker(cv, layer, bbox):
    """Create a highlight set on the specified design and add a rectangle marker."""
    if not isinstance(cv, ae.emyDesign) or not isinstance(layer, str) or not isinstance(bbox, tuple):
        raise TypeError("Invalid types")
    if len(bbox) != 4 or not all(isinstance(x, float) for x in bbox):
        raise TypeError("bbox must be tuple of 4 floats")
    hs = cv.getHighlightSet(ae.SLAY_HYPO, layer)
    if hs is None:
        raise RuntimeError("Failed to get highlight set: not attached to target")
    sel = hs.newSelection()
    if not isinstance(sel, ae.emySelect):
        return None
    for (x, y, w, h) in bbox:
        if not isinstance(x, float) or not all(isinstance(p, float) for p in (y, w, h)):
            raise TypeError("bbox coordinate must be float")
        sel.add(ae.getShapeByBBox(ae.EMY_DRAW_SHA),
                [float(x), float(y), float(x) + float(w), float(y) + float(h)])
    hsq = sel.newQuery()
    rshape = hsq.parseQuery(False)
    if not isinstance(rshape, ae.emyShape):
        return None
    return rshape
